def transform(grid):
    import collections
    g = np.array(grid)
    H, W = g.shape
    twos = [tuple(p) for p in np.argwhere(g == 2)]
    s, t = twos[0], twos[1]
    prev = {s: None}
    q = collections.deque([s])
    while q:
        y, x = q.popleft()
        if (y, x) == t:
            break
        for dy, dx in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < H and 0 <= nx < W and (ny, nx) not in prev:
                if g[ny, nx] == 0 or (ny, nx) == t:
                    prev[(ny, nx)] = (y, x)
                    q.append((ny, nx))
    out = g.copy()
    if t not in prev:
        emit(out, "No path between the two 2 cells; grid unchanged.")
        return out
    path = []
    c = prev[t]
    while c is not None and c != s:
        path.append(c)
        c = prev[c]
    path.reverse()
    # paint the path segment by segment (each straight run is one stage)
    seg_dir = None
    for i, (y, x) in enumerate(path):
        out[y, x] = 4
        if i + 1 < len(path):
            ny, nx = path[i + 1]
            d = (ny - y, nx - x)
            if seg_dir is not None and d != seg_dir:
                emit(out, f"Painted a straight run of the shortest path ending at ({y},{x}); the path turns here.")
            seg_dir = d
    emit(out, "Shortest 4-connected path between the two 2 cells through empty cells is painted 4.")
    return out
